// Structural validation of the Bubble request.
// The shared secret is checked by the Webhook node's Header Auth credential, never here.
const raw = $input.first().json;
const body = raw && raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body) ? raw.body : null;
const errors = [];

function str(v) {
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  return '';
}

function amount(v, label, required) {
  if (v === null || v === undefined || (typeof v === 'string' && v.trim() === '')) {
    if (required) errors.push(label + ' is required');
    return null;
  }
  let n = v;
  if (typeof v === 'string') {
    const t = v.trim();
    if (!/^-?[0-9]+([.][0-9]+)?$/.test(t)) { errors.push(label + ' must be a number'); return null; }
    n = Number(t);
  }
  if (typeof n !== 'number' || !Number.isFinite(n)) { errors.push(label + ' must be a number'); return null; }
  if (n < 0) { errors.push(label + ' must not be negative'); return null; }
  return n;
}

function isoDate(v, label) {
  if (v === null || v === undefined || v === '') return null;
  let d = null;
  if (typeof v === 'number' && Number.isFinite(v)) d = new Date(v);
  else if (typeof v === 'string') d = new Date(v.trim());
  if (!d || isNaN(d.getTime())) { errors.push(label + ' must be a valid date (YYYY-MM-DD)'); return null; }
  return d.toISOString().slice(0, 10);
}

if (!body) errors.push('request body must be a JSON object');
const b = body || {};

const request_id = str(b.request_id);
const author_id = str(b.author_id);
const author_name = str(b.author_name);
const author_email = str(b.author_email).toLowerCase();

if (!request_id) errors.push('request_id is required');
else if (request_id.length > 200) errors.push('request_id must be 200 characters or fewer');
if (!author_id) errors.push('author_id is required');
if (!author_name) errors.push('author_name is required');
if (!author_email) errors.push('author_email is required');
else if (!/^[^ @]+@[^ @]+[.][^ @]+$/.test(author_email)) errors.push('author_email is not a valid email address');

const total_earned = amount(b.total_earned, 'total_earned', true);
const total_paid = amount(b.total_paid, 'total_paid', true);
const total_pending = amount(b.total_pending, 'total_pending', true);

const books = [];
if (!Array.isArray(b.books) || b.books.length === 0) {
  errors.push('books must be a non-empty array');
} else {
  b.books.forEach(function (bk, i) {
    const label = 'books[' + i + ']';
    if (!bk || typeof bk !== 'object' || Array.isArray(bk)) { errors.push(label + ' must be an object'); return; }
    const title = str(bk.title);
    const status = str(bk.status);
    if (!title) errors.push(label + '.title is required');
    if (!status) errors.push(label + '.status is required');
    const copies = amount(bk.total_copies_sold, label + '.total_copies_sold', false);
    if (copies !== null && !Number.isInteger(copies)) errors.push(label + '.total_copies_sold must be a whole number');
    books.push({
      book_id: str(bk.book_id),
      title: title,
      status: status,
      is_published: status.toLowerCase() === 'published',
      total_copies_sold: copies,
      total_royalty_earned: amount(bk.total_royalty_earned, label + '.total_royalty_earned', false),
      royalty_paid: amount(bk.royalty_paid, label + '.royalty_paid', false),
      royalty_pending: amount(bk.royalty_pending, label + '.royalty_pending', false),
      last_royalty_payout_date: isoDate(bk.last_royalty_payout_date, label + '.last_royalty_payout_date'),
    });
  });
}

// Optional fields (never invented when absent)
const reporting_period = str(b.reporting_period);
const reporting_period_end = isoDate(b.reporting_period_end, 'reporting_period_end');
const currency = str(b.currency).slice(0, 10);

const valid = errors.length === 0;
return [{
  json: {
    valid: valid,
    error_code: valid ? '' : 'INVALID_PAYLOAD',
    error_message: valid ? '' : 'Invalid request: ' + errors.join('; '),
    request_id: request_id,
    author_id: author_id,
    author_name: author_name,
    author_email: author_email,
    total_earned: total_earned,
    total_paid: total_paid,
    total_pending: total_pending,
    currency: currency,
    reporting_period: reporting_period,
    reporting_period_end: reporting_period_end,
    books: books,
    received_at: new Date().toISOString(),
  },
}];

// Cross-checks the supplied royalty figures. Values are never modified:
// any conflict is flagged and the request fails.
const req = $('Validate Request Format').first().json;
// Structurally invalid request: fail it here (after the duplicate check) without AI processing
if (!req.valid) {
  return [{ json: { request_id: req.request_id, author_id: req.author_id, totals_consistent: false, error_code: req.error_code, error_message: req.error_message, computed_book_sums: null, check_notes: [], ai_input: null } }];
}
const TOL = 0.01;
const issues = [];
const notes = [];
function near(a, b) { return Math.abs(a - b) <= TOL; }
function r2(n) { return Math.round(n * 100) / 100; }

// Author-level: earned - paid must equal pending
if (!near(req.total_earned - req.total_paid, req.total_pending)) {
  issues.push('total_earned (' + req.total_earned + ') minus total_paid (' + req.total_paid + ') is ' + r2(req.total_earned - req.total_paid) + ', but total_pending is ' + req.total_pending);
}

// Book-level: earned - paid must equal pending when all three are supplied
req.books.forEach(function (bk) {
  const e = bk.total_royalty_earned, p = bk.royalty_paid, q = bk.royalty_pending;
  if (e !== null && p !== null && q !== null) {
    if (!near(e - p, q)) issues.push('book "' + bk.title + '": earned (' + e + ') minus paid (' + p + ') is ' + r2(e - p) + ', but royalty_pending is ' + q);
  } else {
    notes.push('book "' + bk.title + '" is missing one or more royalty amounts; per-book check skipped');
  }
});

// Sum of books vs author totals, only when every book supplies the field
function sumField(f) {
  for (const bk of req.books) { if (typeof bk[f] !== 'number') return null; }
  return r2(req.books.reduce(function (s, bk) { return s + bk[f]; }, 0));
}
const sums = {
  earned: sumField('total_royalty_earned'),
  paid: sumField('royalty_paid'),
  pending: sumField('royalty_pending'),
};
[['earned', 'total_earned'], ['paid', 'total_paid'], ['pending', 'total_pending']].forEach(function (pair) {
  const s = sums[pair[0]];
  if (s === null) { notes.push('sum of book ' + pair[0] + ' royalties not checked: some books lack this value'); return; }
  if (!near(s, req[pair[1]])) issues.push('sum of book ' + pair[0] + ' royalties is ' + s + ', but ' + pair[1] + ' is ' + req[pair[1]]);
});

// Expected payout estimate only when a reporting period end date was supplied
let expected = '';
if (req.reporting_period_end) {
  const d = new Date(req.reporting_period_end + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + 45);
  expected = d.toISOString().slice(0, 10);
}

const published = req.books.filter(function (bk) { return bk.is_published; });
const others = req.books.filter(function (bk) { return !bk.is_published; });

const ai_input = {
  author_name: req.author_name,
  author_email: req.author_email,
  total_copies_sold: req.books.every(function (bk) { return typeof bk.total_copies_sold === 'number'; }) ? req.books.reduce(function (s, bk) { return s + bk.total_copies_sold; }, 0) : null,
  currency: req.currency,
  reporting_period: req.reporting_period,
  reporting_period_end: req.reporting_period_end || '',
  expected_payout_by_estimate: expected,
  totals: { total_earned: req.total_earned, total_paid: req.total_paid, total_pending: req.total_pending },
  all_royalties_paid: req.total_pending === 0 && req.total_earned > 0,
  published_books: published.map(function (bk) {
    return {
      title: bk.title,
      copies_sold: bk.total_copies_sold,
      royalties_earned: bk.total_royalty_earned,
      royalties_paid: bk.royalty_paid,
      royalties_pending: bk.royalty_pending,
      last_payout_date: bk.last_royalty_payout_date,
    };
  }),
  other_books: others.map(function (bk) { return { title: bk.title, status: bk.status }; }),
};

const ok = issues.length === 0;
return [{
  json: {
    request_id: req.request_id,
    author_id: req.author_id,
    totals_consistent: ok,
    error_code: ok ? '' : 'TOTALS_DISCREPANCY',
    error_message: ok ? '' : 'Royalty totals discrepancy (values were not changed): ' + issues.join('; '),
    computed_book_sums: sums,
    check_notes: notes,
    ai_input: ai_input,
  },
}];

